    parts=[p for p in line.split(' - ') if any(k in p for k in ('val-','global_step','response_length/','score/mean','entropy','kl_loss','pg_loss','grad_norm','clip_ratio','aborted','num_tokens','timing_s/step','timing_s/testing'))]
    print('\n'.join(parts))
else:
    print("no step150 metric line found")
